spec.expr:
(
  avg_over_time(node_sensor_power{instance="$instance"}[1d]) 
  * 24 / 1000
)
/ on(instance)
(
  avg_over_time(
    sum by(instance) (
      node_condor_cpu{instance="$instance"} 
      * on(instance) group_left() 
      node_corepower_hs23{instance="$instance"}
    )[1d:5m]
  ) 
  * 24
)
